import{_ as n,C as s,o as e,c as u,j as i,E as r,a as o,a2 as t}from"./chunks/framework.C21TwvGF.js";const P=JSON.parse(`{"title":"3-dars (Mentor). IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","description":"","frontmatter":{"title":"3-dars (Mentor). IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"week":{"n":1,"link":"/mentor/9-sinf-iot/hafta-01/"},"g":3,"title":"IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","lead":"IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-3-test.html","student_link":"/9-sinf-iot/hafta-01/dars-3","tabs":[{"g":1,"link":"/mentor/9-sinf-iot/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-iot/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-iot/hafta-01/dars-3","current":true}],"prev":{"g":2,"title":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","link":"/mentor/9-sinf-iot/hafta-01/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-01/dars-3.md","filePath":"mentor/9-sinf-iot/hafta-01/dars-3.md"}`),d={name:"mentor/9-sinf-iot/hafta-01/dars-3.md"},m={class:"blk"},h={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},q={id:"mentor-konspekti",tabindex:"-1"},b={class:"blk"},k={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},v={class:"blk"},y={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},f={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function p(T,a,z,x,_,I){const l=s("Icon");return e(),u("div",null,[i("div",m,[i("h2",h,[r(l,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=t("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga IoT tizimlarining yuqori qatlamlarini — tarmoq texnologiyalari (Wi-Fi, Bluetooth BLE, ZigBee, LoRaWAN, 4G/5G) va protokollarini (MQTT, HTTP), Edge computing va Cloud computing arxitekturalarini, ma&#39;lumotlarni filtrlash va xavfsizlikni hamda foydalanuvchi interfeysi (UI dashboardlar, mobil ilovalar, bildirishnomalar)ni o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar IoT tarmoqlarini masofa va energiya sarfiga qarab to&#39;g&#39;ri tanlay oladi; MQTT protokoli (Publish/Subscribe, Broker) ishlash mexanizmini tushunadi; Edge computing va Cloud computing farqini biladi; IoT telemetriya ma&#39;lumotlarini dashboardlarda vizualizatsiya qilish tamoyillarini o&#39;zlashtiradi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (Sensorlar, aktuatorlar va Arduino): 10 daqiqa</li><li>Yangi mavzu: Tarmoq texnologiyalari (Wi-Fi, BLE, LoRaWAN) va protokollar (MQTT vs HTTP): 25 daqiqa</li><li>Bulutli tizimlar, Edge Computing va kiberxavfsizlik: 20 daqiqa</li><li>Ilova qatlami (Dashboardlar, mobil ilovalar): 15 daqiqa</li><li>Dars yakuni va nazorat savollari: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",q,[r(l,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=t('<h3 id="_1-iot-tarmoq-texnologiyalari-connectivity" tabindex="-1">1. IoT Tarmoq Texnologiyalari (Connectivity) <a class="header-anchor" href="#_1-iot-tarmoq-texnologiyalari-connectivity" aria-label="Permalink to &quot;1. IoT Tarmoq Texnologiyalari (Connectivity)&quot;">​</a></h3><p>IoT qurilmalari o&#39;z sharoiti, masofasi va quvvat manbaiga qarab turli tarmoqlardan foydalanadi:</p><ol><li><strong>Wi-Fi (IEEE 802.11):</strong> Yuqori tezlik (Mbps), qamrov 10–50 m. Energiya sarfi yuqori. Doimiy elektr tarmog&#39;iga ulangan aqlli uy qurilmalari, videokameralar uchun.</li><li><strong>Bluetooth Low Energy (BLE):</strong> Qisqa masofa (1–20 m), juda kam quvvat sarfi. Smart soatlar, fitnes bilakuzuklar va tibbiy sensorlar uchun.</li><li><strong>ZigBee:</strong> Qamrov 10–100 m, past tezlik, o&#39;zaro to&#39;rsimon (<strong>Mesh network</strong>) ulanadi (har bir qurilma signalni keyingisiga uzatadi). Ko&#39;p datchikli aqlli uylar uchun.</li><li><strong>LoRaWAN (Long Range WAN):</strong> Uzoq masofa (shahar tashqarisida 10–15 km), juda past tezlik (bir necha bayt), batareyada <strong>5–10 yil</strong> ishlaydi. Qishloq xo&#39;jaligi, o&#39;rmon yong&#39;inlari va suv omborlari monitoringi uchun.</li><li><strong>NB-IoT / LTE-M va 4G/5G:</strong> Mobil operatorlar infratuzilmasi orqali shahar bo&#39;ylab harakatlanuvchi transportlar va aqlli hisoblagichlar (gaz, elektr) uchun.</li></ol><h3 id="_2-iot-protokollari-mqtt-vs-http" tabindex="-1">2. IoT Protokollari: MQTT vs HTTP <a class="header-anchor" href="#_2-iot-protokollari-mqtt-vs-http" aria-label="Permalink to &quot;2. IoT Protokollari: MQTT vs HTTP&quot;">​</a></h3><ul><li><strong>HTTP / REST API (Request / Response):</strong><ul><li>Mijoz so&#39;rov yuboradi, server javob beradi. Har bir so&#39;rovda katta sarlavhalar (headers) mavjud.</li><li>IoT uchun kamchiligi: og&#39;ir, ortiqcha internet-trafik va quvvat sarflaydi.</li></ul></li><li><strong>MQTT (Message Queuing Telemetry Transport):</strong><ul><li>IoT ning oltin standarti! IBM tomonidan 1999 yilda neft quvurlarini sun&#39;iy yo&#39;ldosh orqali monitoring qilish uchun yaratilgan.</li><li><strong>Publish / Subscribe (Nashr / Obuna) modeli:</strong><ul><li><em>Broker (Markaziy server):</em> Xabarlarni qabul qiladi va tarqatadi (masalan, Mosquitto, EMQX).</li><li><em>Publisher (Yuboruvchi):</em> Sensor ma&#39;lumotni ma&#39;lum bir mavzuga (Topic) jo&#39;natadi (masalan: <code>home/kitchen/temp</code> -&gt; <code>24.5</code>).</li><li><em>Subscriber (Qabul qiluvchi):</em> Smartfon ilovasi yoki fan ushbu mavzuga obuna bo&#39;ladi va yangi ma&#39;lumot kelishi bilan uni darhol qabul qiladi.</li><li>Sarlavha hajmi atigi <strong>2 bayt</strong> — zaif mobil tarmoqlarda ham uzluksiz ishlaydi.</li></ul></li></ul></li></ul><h3 id="_3-edge-computing-vs-cloud-computing" tabindex="-1">3. Edge Computing vs Cloud Computing <a class="header-anchor" href="#_3-edge-computing-vs-cloud-computing" aria-label="Permalink to &quot;3. Edge Computing vs Cloud Computing&quot;">​</a></h3><ul><li><strong>Cloud Computing (Bulutli hisoblash):</strong><ul><li>Barcha ma&#39;lumotlar uzoqdagi serverlarga (AWS, Azure, Blynk) yuboriladi.</li><li>Katta hajmdagi ma&#39;lumotlarni saqlash, yillik tahlillar va murakkab ML algoritmlari uchun a&#39;lo.</li><li>Kamchiligi: internet uzilsa yoki kechikish (latency) bo&#39;lsa, xavfli vaziyatda kechikishi mumkin.</li></ul></li><li><strong>Edge Computing (Chekka / Lokal hisoblash):</strong><ul><li>Ma&#39;lumotlar bulutga ketmasdan, bevosita qurilmaning o&#39;zida (ESP32) yoki xonadagi Gateway&#39;da tahlil qilinadi.</li><li>Tezkor javob (1 millisekund): gaz sezilsa, bulutga so&#39;rov yuborib o&#39;tirmay, mikrokontroller darhol klapanni yopadi!</li><li>Internet o&#39;chsa ham lokal xavfsizlik 100% ishlayveradi.</li></ul></li></ul><h3 id="_4-ilova-qatlami-va-ma-lumotlarni-vizualizatsiya-qilish" tabindex="-1">4. Ilova Qatlami va Ma&#39;lumotlarni Vizualizatsiya Qilish <a class="header-anchor" href="#_4-ilova-qatlami-va-ma-lumotlarni-vizualizatsiya-qilish" aria-label="Permalink to &quot;4. Ilova Qatlami va Ma&#39;lumotlarni Vizualizatsiya Qilish&quot;">​</a></h3><ul><li><strong>Dashboard (Boshqaruv paneli):</strong> Sensorlardan kelayotgan raqamlar oqimini inson tushunadigan shaklga aylantirish: <ul><li>Harorat va namlik grafigi (dinamika);</li><li>Status indikatorlari (Yashil/Qizil chiroq);</li><li>Boshqaruv tugmalari (On/Off switch).</li></ul></li><li>Mashhur IoT platformalari: <strong>Blynk</strong>, <strong>Ubidots</strong>, <strong>ThingsBoard</strong>, <strong>Home Assistant</strong>.</li></ul><hr>',10))]),i("div",b,[i("h2",k,[r(l,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=t('<h3 id="_1-topshiriq-aloqa-texnologiyasini-tanlash-oson" tabindex="-1">1-topshiriq. Aloqa texnologiyasini tanlash (oson) <a class="header-anchor" href="#_1-topshiriq-aloqa-texnologiyasini-tanlash-oson" aria-label="Permalink to &quot;1-topshiriq. Aloqa texnologiyasini tanlash (oson)&quot;">​</a></h3><p>Quyidagi 3 ta IoT loyihasi uchun eng mos keluvchi simsiz tarmoqni (Wi-Fi, Bluetooth BLE yoki LoRaWAN) tanlang va asoslang:</p><ol><li>Bemorning bilagiga taqilgan puls-oksimetr datchigi;</li><li>Shahardan 10 km uzoqlikdagi paxta dalasidagi tuproq namligi sensori;</li><li>Uy xonasidagi yuqori aniqlikdagi xavfsizlik videokamerasi.</li></ol><p><strong>Yechim:</strong></p><ol><li><strong>Puls-oksimetr:</strong> <code>Bluetooth Low Energy (BLE)</code> — juda kam energiya sarflaydi, kichik batareyada oylarcha ishlaydi va bemorning cho&#39;ntagidagi smartfon bilan yaqin masofada bog&#39;lanadi.</li><li><strong>Paxta dalasi sensori:</strong> <code>LoRaWAN</code> — 10-15 km masofaga ma&#39;lumot uzata oladi va elektr simi bo&#39;lmagan dalada batareyasi 5 yilgacha yetadi.</li><li><strong>Videokamera:</strong> <code>Wi-Fi</code> — katta hajmdagi video oqimini (HD video) uzatish uchun yuqori o&#39;tkazuvchanlik tezligi (Mbps) talab etiladi.</li></ol><h3 id="_2-topshiriq-mqtt-mavzusi-topic-va-xabarlar-oqimi-o-rta" tabindex="-1">2-topshiriq. MQTT mavzusi (Topic) va xabarlar oqimi (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-mqtt-mavzusi-topic-va-xabarlar-oqimi-o-rta" aria-label="Permalink to &quot;2-topshiriq. MQTT mavzusi (Topic) va xabarlar oqimi (o&#39;rta)&quot;">​</a></h3><p>Aqlli uyda 3 ta xona bor: <code>mehmonxona</code>, <code>oshxona</code>, <code>yotoqxona</code>. Har bir xonada harorat va yorug&#39;lik sensorlari o&#39;rnatilgan. MQTT daraxtsimon ierarxiyasi bo&#39;yicha ushbu xonalardagi haroratni yuborish uchun 3 ta to&#39;g&#39;ri mavzu (Topic) nomini tuzing va smartfon qanday qilib bir vaqtning o&#39;zida barcha xonalar haroratiga bitta so&#39;rov bilan obuna bo&#39;lishi mumkinligini tushuntiring.</p><p><strong>Yechim:</strong></p><ol><li><strong>Topic nomlari:</strong><ul><li>Mehmonxona: <code>uy/mehmonxona/harorat</code></li><li>Oshxona: <code>uy/oshxona/harorat</code></li><li>Yotoqxona: <code>uy/yotoqxona/harorat</code></li></ul></li><li><strong>Umumiy obuna:</strong><ul><li>MQTT da <code>+</code> (bitta darajali wildcard) belgisi ishlatiladi.</li><li>Smartfon ilovasi <code>uy/+/harorat</code> mavzusiga obuna bo&#39;lsa, u barcha xonalardan kelgan harorat xabarlarini avtomatik qabul qiladi.</li></ul></li></ol><h3 id="_3-topshiriq-nega-gaz-sizib-chiqqanda-cloud-emas-edge-computing-kerak-qiyin" tabindex="-1">3-topshiriq. Nega gaz sizib chiqqanda Cloud emas, Edge Computing kerak? (qiyin) <a class="header-anchor" href="#_3-topshiriq-nega-gaz-sizib-chiqqanda-cloud-emas-edge-computing-kerak-qiyin" aria-label="Permalink to &quot;3-topshiriq. Nega gaz sizib chiqqanda Cloud emas, Edge Computing kerak? (qiyin)&quot;">​</a></h3><p>Oshxonada gaz sizib chiqishini aniqlovchi xavfsizlik tizimi o&#39;rnatilgan. Agar tizim faqat Cloud Computing asosida ishlasa va to&#39;satdan uydagi Wi-Fi router yoki tashqi internet aloqasi uzilib qolsa, qanday fojia sodir bo&#39;lishi mumkin? Ushbu muammo Edge Computing yordamida qanday hal qilinadi?</p><p><strong>Yechim:</strong></p><ol><li><strong>Faqat Cloud bo&#39;lsa:</strong> Sensor gazni sezadi, lekin ma&#39;lumotni bulutga yubora olmaydi (internet yo&#39;q). Bulutdan &quot;Klapanni yop!&quot; buyrug&#39;i kelmagani uchun gaz xonaga to&#39;lishda davom etadi va portlash xavfi yuzaga keladi.</li><li><strong>Edge Computing yechimi:</strong><ul><li>Qaror qabul qilish mantiqi to&#39;g&#39;ridan-to&#39;g&#39;ri mikrokontrollerning (masalan, Arduino yoki ESP32) o&#39;ziga yoziladi.</li><li>Sensor signali belgilangan xavfli chegaradan oshishi bilan mikrokontroller internetga qaramasdan, 10 millisekund ichida relega signal berib, gaz klapanini zudlik bilan yopadi va ovozli buzzerni yoqadi.</li><li>Internet mavjud bo&#39;lganda esa qo&#39;shimcha ravishda bulutga xabar yuboriladi.</li></ul></li></ol><hr>',14))]),i("div",v,[i("h2",y,[r(l,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=t("<ol><li>IoT uchun eng yengil va ommabop hisoblangan Publish/Subscribe protokoli qaysi? <ul><li><em>Javob:</em> MQTT (Message Queuing Telemetry Transport).</li></ul></li><li>Qaysi simsiz tarmoq texnologiyasi shahar tashqarisida 10–15 km masofaga kam quvvat sarfi bilan ma&#39;lumot uzatish imkonini beradi? <ul><li><em>Javob:</em> LoRaWAN.</li></ul></li><li>Edge Computing bilan Cloud Computing o&#39;rtasidagi asosiy farq nima? <ul><li><em>Javob:</em> Edge Computing ma&#39;lumotlarni bevosita qurilmaning o&#39;zida tezkor tahlil qiladi (internet talab qilmaydi); Cloud Computing esa ma&#39;lumotlarni uzoq serverlarda saqlaydi va global tahlil qiladi.</li></ul></li><li>Smartfonda sensor ko&#39;rsatkichlarini grafik va tugmalar ko&#39;rinishida chiqarib beruvchi mashhur IoT mobil platformasi qaysi? <ul><li><em>Javob:</em> Blynk (yoki Ubidots, ThingsBoard).</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",f,[r(l,{name:"file-text"}),a[12]||(a[12]=o(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,[i("strong",null,"HTTP va MQTT ni chalkashtirish:"),o(" O'quvchilar sensor har 1 soniyada serverga ma'lumot yuborishi uchun og'ir HTTP POST so'rovini qo'llashga harakat qilishadi. Bu mikrokontroller xotirasini to'ldirib, batareyani bir kunda tugatadi. Sensor telemetriyasi uchun har doim MQTT tavsiya etiladi.")]),i("li",null,[i("strong",null,"Lokal xavfsizlikni unutish (Cloud dependency):"),o(" Barcha funksiyalarni faqat bulutga bog'lab qo'yish (masalan, chiroqni yoqish uchun internet orqali buyruq kutish). Internet uzilganda ham xona chirog'i yoki gaz xavfsizligi lokal ravishda mustaqil ishlashi shart.")])],-1))])])}const S=n(d,[["render",p]]);export{P as __pageData,S as default};
